CREATE OR REPLACE FUNCTION p2412175g31152gg1() RETURNS INTEGER AS $$
DECLARE
    x INTEGER := 0;
    y INTEGER := 0;
    total INTEGER := 0;
BEGIN
    <<x_loop>>
    LOOP
        x := x + 1;
        y := 0;

        <<y_loop>>
        LOOP
            y := y + 1;
            CONTINUE x_loop WHEN x = 2 AND y = 2;
            total := total + (x * y);
