CREATE OR REPLACE FUNCTION p2412175g31155gg1(limit_num INTEGER)
RETURNS INTEGER[]
LANGUAGE plpgsql
AS $$
DECLARE
    primes INTEGER[] := ARRAY[]::INTEGER[];
    num INTEGER := 2;
    is_prime BOOLEAN;
    divisor INTEGER;
BEGIN
    LOOP
        is_prime := TRUE;
        divisor := 2;
        WHILE divisor * divisor <= num LOOP
            IF num % divisor = 0 THEN
                is_prime := FALSE;
                EXIT;
            END IF;
            divisor := divisor + 1;
        END LOOP;
        IF is_prime THEN
            primes := primes || num;
        END IF;
        num := num + 1;
        EXIT WHEN num > limit_num;
    END LOOP;
    RETURN primes;
END;
$$;

